    const l1 = Math.hypot(bx - ax, by - ay), l2 = Math.hypot(cx - bx, cy - by), k = Math.min(r, l1 / 2, l2 / 2);
    if (!k) { d += `L${f(bx)},${f(by)}`; continue; }
