const newsExcerpt = (body, U) => esc(String(body || '').replace(/\s+/g, ' ').replace(/\*\*|__|~~|`/g, '').replace(/(^|[^*\w])\*([^*\s][^*]*?)\*(?!\w)/g, '$1$2').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1').trim())
