  if (S.nf.err && !S.nf.items) return bar + `<div class="empty">${S.nf.err === 'offline' ? tr('News are only available online.') : esc(S.nf.err)}</div>`;
  const mine = S.nf.items && S.nf.f === f ? S.nf.items : null;
