const AV_PRESETS = [['coffee', N_('Coffee')], ['headphones', N_('Headphones')], ['camera', N_('Camera')], ['sleepy', N_('Sleepy')], ['laptop', N_('Laptop')],
  ['plant', N_('Plant')], ['robot', N_('Robot')], ['shades', N_('Sunglasses')], ['party', N_('Party')], ['glasses', N_('Reading')]];
