    const b = e.target.closest('[data-tfa]'); if (!b) return;
    if (b.dataset.tfa === 'rc') { recovery = true; draw(); }
    if (b.dataset.tfa === 'back2') { recovery = false; draw(); }
    if (b.dataset.tfa === 'restart') location.replace('/');
