// ------------------------------------------------------------------ 2.0.2: list editing, keyboard, recently viewed, list icons, agent typing
// ---- #182 edit a title right in the list: double-click (desktop) or E / F2 on the keyboard-focused row. Enter saves (one
// undo step), Esc cancels, leaving the field saves. A re-render (sync) keeps the field, its text and the caret.
S.ie = null;  // {id, v, s, e}
function inlineEditStart(id) {
  const t = taskById(id);
  if (!t || !(t.id > 0)) return;
  if (!canEdit(t)) { roToast(); return; }
  if (!$(`#view .trow[data-id="${id}"] .ttl`)) return;
  if (S.ie && S.ie.id !== id) inlineEditCommit();
  S.ie = {id, v: t.title};
  inlineEditMount(true);
}
function inlineEditMount(focus) {
  const ie = S.ie; if (!ie) return;
  const row = $(`#view .trow[data-id="${ie.id}"]`), ttl = row && $('.ttl', row);
  if (!ttl) return;
  if ($('.ttlin', ttl)) return;
  row.classList.add('iedit'); row.removeAttribute('draggable');
  ttl.innerHTML = `<input class="ttlin" value="${esc(ie.v)}" aria-label="${esc(tr('Title'))}" maxlength="500" enterkeyhint="done" autocomplete="off">`;
  const i = $('.ttlin', ttl);
  i.addEventListener('input', () => { ie.v = i.value; });
  i.addEventListener('keydown', e => {
    if (e.isComposing) return;
    if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); inlineEditCommit(true); }
    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); inlineEditCancel(); }
    else e.stopPropagation();  // j / k / x … are text here
  });
  i.addEventListener('blur', () => setTimeout(() => { if (S.ie === ie && !(document.activeElement && document.activeElement.classList.contains('ttlin'))) inlineEditCommit(); }, 0));
  if (focus) { i.focus(); const s = ie.s ?? i.value.length, en = ie.e ?? i.value.length; try { i.setSelectionRange(s, en); } catch { /* ignore */ } }
}
async function inlineEditCommit(keepFocus) {
  const ie = S.ie; if (!ie) return;
  S.ie = null;
  const t = taskById(ie.id), v = String(ie.v || '').replace(/\s+/g, ' ').trim().slice(0, 500);
  if (t && v && v !== t.title) {
    try { await patchUndoable(ie.id, {title: v}, tr('Renamed to {0}', qn(v.slice(0, 40)))); } catch { /* api() showed it */ }
  }
  renderView();
  if (keepFocus) kfocus(ie.id);
}
function inlineEditCancel() { const ie = S.ie; S.ie = null; renderView(); if (ie) kfocus(ie.id); }
document.addEventListener('dblclick', e => {
  const r = e.target.closest?.('#view .trow');
  if (!r || isTouch() || S.multiMode || !e.target.closest('.tmain') || e.target.closest('button,a,input,.ttlin')) return;
  e.preventDefault(); window.getSelection?.()?.removeAllRanges?.();
  inlineEditStart(+r.dataset.id);
});

// ---- #283 "+" on a section header: an input right below it, Enter adds the task there and stays open for the next one
S.secAdd = null;  // {key, sec, v}
function secAddOpen(sec) {
  S.secAdd = {key: S.route.key, sec: sec || 0, v: ''};
  S.collapsed.delete('s:' + (sec || 0)); LS.set('collapsed', [...S.collapsed]);
  renderView();
  $('#view .secadd-in')?.focus();
}
function secAddHtml(g) {
  const sa = S.secAdd;
  if (!sa || sa.key !== S.route.key || sa.sec !== (g.section || 0)) return '';
  return `<div class="secadd">${ic('plus', 's')}<input class="secadd-in" data-sec="${g.section || 0}" placeholder="${esc(tr('Add a task to {0}', g.name))}" aria-label="${esc(tr('Add a task to {0}', g.name))}" enterkeyhint="done" autocomplete="off"></div>`;
}
async function secAddSubmit(inp) {
  const sa = S.secAdd, text = inp.value.trim(); if (!sa || !text) return;
  const lid = routeList()?.id; if (!lid) return;
  const r = parseQuick(text, new Set());
  inp.value = ''; sa.v = '';
  try {
    await createTask({title: (r.title || text).slice(0, 500), list_id: lid, section_id: sa.sec || null, due: r.due || null, due_time: r.due_time,
      priority: r.priority ?? 0, tags: r.tags || [], repeat: r.repeat || ''});
  } catch { inp.value = text; sa.v = text; }
  $('#view .secadd-in')?.focus();
}
document.addEventListener('keydown', e => {
  const i = e.target; if (!i.classList?.contains('secadd-in')) return;
  if (e.isComposing) return;
  if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); secAddSubmit(i); }
  else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); S.secAdd = null; renderView(); }
}, true);
document.addEventListener('input', e => { if (e.target.classList?.contains('secadd-in') && S.secAdd) S.secAdd.v = e.target.value; });
document.addEventListener('focusout', e => {
  const i = e.target; if (!i.classList?.contains('secadd-in')) return;
  setTimeout(() => { if (S.secAdd && !S.secAdd.v && !(document.activeElement && document.activeElement.classList.contains('secadd-in')) && !S.secAdd.keep) { S.secAdd = null; renderView(); } }, 150);
});

// ---- #284 collapse / expand everything of the view: section groups and tasks with subtasks (remembered per device)
function collapseKeys() {
  if (S.route.mod !== 'tasks' || isKanban() || isTimeline() || isRoadmap() || NOLIST_KEYS.includes(S.route.key)) return [];
  const keys = [], walk = t => { const k = children(t.id).filter(x => x.status === 0); if (k.length) { keys.push('t' + t.id); k.forEach(walk); } };
  for (const g of groupTasks(viewTasks())) { if (g.name) keys.push(g.id); g.tasks.forEach(walk); }
  return keys;
}
function collapseAll(close) {
  const keys = collapseKeys(); if (!keys.length) return;
  for (const k of keys) close ? S.collapsed.add(k) : S.collapsed.delete(k);
  LS.set('collapsed', [...S.collapsed]); renderView();
  toast(close ? tr('Everything collapsed') : tr('Everything expanded'));
}
const collapseAnyOpen = () => collapseKeys().some(k => !S.collapsed.has(k));
function collapseItems() {
  const keys = collapseKeys(); if (!keys.length) return [];
  const open = keys.some(k => !S.collapsed.has(k)), closed = keys.some(k => S.collapsed.has(k));
  return [{label: tr('Collapse all'), icon: 'chev', dis: !open, keys: 'Shift+C', fn: () => collapseAll(true)},
    {label: tr('Expand all'), icon: 'sub', dis: !closed, fn: () => collapseAll(false)}];
}

// ---- #184 recently viewed tasks and lists (per device, the last 5) on top of the command palette
function recentPush(kind, id) {
  if (!(id > 0)) return;
  const k = kind + ':' + id;
  LS.set('recentViewed', [k, ...LS.get('recentViewed', []).filter(x => x !== k)].slice(0, 5));
}
function palOpenTask(x) {
  const r = $(`#view .trow[data-id="${x.id}"]`);
  if (!r && x.list_id) go(x.list_id === inbox()?.id ? 'inbox' : 'l/' + x.list_id);
  setTimeout(() => openDetail(x.id), 30);
}
function palViewed() {
  return LS.get('recentViewed', []).map(k => {
    const [kind, v] = k.split(':'), id = +v;
    if (kind === 't') {
      const t = taskById(id); if (!t || t.deleted_at) return null;
      return {id: 'rv:' + k, kind: 'tasks', label: t.title, icon: t.status === 2 ? 'done' : 'check', group: 'viewed', fn: () => palOpenTask(t),
        sub: [lname(listById(t.list_id)), t.due ? dayLabel(t.due) : ''].filter(Boolean).join('  ·  ')};
    }
    if (kind === 'l') {
      const l = listById(id); if (!l || l.archived) return null;
      return {id: 'rv:' + k, kind: 'list', label: l.is_inbox ? tr('Inbox') : lname(l), icon: 'list', sw: cssColor(l.color), img: l.icon || '', group: 'viewed', fn: () => go(l.is_inbox ? 'inbox' : 'l/' + l.id)};
    }
    return null;
  }).filter(Boolean);
}

// ---- #245 own list icons: a picture instead of the emoji (presets: the app icon + the sloths, or an own picture, cropped
// square like the profile picture). Shown wherever the emoji / colour dot of the list shows. An emoji still works; picking
// one removes the picture and the other way round.
const LICON_PRESETS = [['kalmido', 'Kalmido'], ...AV_PRESETS];
const liconSrc = k => k === 'kalmido' ? '/static/icon.svg' : `/static/avatars/${k}.svg`;
const licon = (l, cls = 'licon') => l && l.icon ? `<img class="${cls}" src="${esc(l.icon)}" alt="" loading="lazy" decoding="async">` : '';
function liconPickHtml(l) {
  const cur = l.icon || '';
  return `<div class="lipick" role="group" aria-label="${esc(tr('Picture'))}">${LICON_PRESETS.map(([k, n]) => `<button type="button" class="avopt ${cur === liconSrc(k) ? 'on' : ''}" data-licon="${k}" title="${esc(k === 'kalmido' ? n : tr(n))}" aria-label="${esc(k === 'kalmido' ? n : tr(n))}" aria-pressed="${cur === liconSrc(k)}"><img src="${liconSrc(k)}" alt=""></button>`).join('')}` +
    `<button type="button" class="avopt up ${cur.startsWith('/api/list-icon/') ? 'on' : ''}" data-licon="upload" title="${esc(tr('Upload a picture…'))}" aria-label="${esc(tr('Upload a picture…'))}">${cur.startsWith('/api/list-icon/') ? `<img src="${esc(cur)}" alt="">` : ic('plus')}</button>` +
    (cur ? `<button type="button" class="avopt none" data-licon="none" title="${esc(tr('Remove the picture'))}" aria-label="${esc(tr('Remove the picture'))}">${ic('ban', 's')}</button>` : '') + '</div>';
}
async function liconSet(lid, how) {
  let j;
  try {
    if (how === 'none') j = await api('DELETE', `/api/lists/${lid}/icon`);
    else if (how instanceof Blob) { const fd = new FormData(); fd.append('file', how, 'icon.png'); j = await api('POST', `/api/lists/${lid}/icon`, fd); }
    else j = await api('PUT', `/api/lists/${lid}/icon`, {preset: how});
  } catch { return null; }
  const l = listById(lid); if (l) l.icon = j.icon || '';
  await load().catch(() => {}); render();
  return j.icon || '';
}
function liconUpload(lid) {
  return new Promise(res => {
    const inp = document.createElement('input'); inp.type = 'file'; inp.accept = 'image/jpeg,image/png,image/webp,image/gif';
    inp.addEventListener('change', async () => {
      const f = inp.files?.[0]; if (!f) { res(null); return; }
      if (f.size > 8 * 1024 * 1024) { toast(tr('The picture is too large (at most {0} MB)', 8)); res(null); return; }
      const bl = await avCropModal(f, {title: tr('List icon'), png: true}); if (!bl) { res(null); return; }
      res(await liconSet(lid, bl));
    });
    inp.click();
  });
}

// ---- #299 "Claude is writing …": while an agent reports "working", under the last chat message and in the comment area of
// the task it works on (status task_id, a running job on the task, else every task of its lists); a spinning ring on the
// header chip / the agents button everywhere; "waiting" = an accent dot instead
const workingAgents = () => (S.agents || []).filter(a => a.enabled && a.status === 'working');
function taskTypers(t) {
  if (!t || !(t.id > 0) || t.context) return [];
  const mine = new Set(taskAgents(t).map(a => a.id));
  return workingAgents().filter(a => a.status_task === t.id || (a.job_tasks || []).includes(t.id) || (!a.status_task && mine.has(a.id)));
}
function typingHtml(ags, id) {
  if (!ags.length) return `<div class="atyping hidden" id="${id}" role="status" aria-live="polite"></div>`;
  // 2.13.2 (#478 F6): "is writing …" (dots) only for a real typing signal (or the chat's answer on its way); an agent that
  // only reports "working" on the task "is working on it"
  const wr = a => id === 'chat-typing' || (a.typing || 0) - agentAge() > 0, any = ags.some(wr);
  return `<div class="atyping" id="${id}" role="status" aria-live="polite">${any ? '<span class="atdots" aria-hidden="true"><i></i><i></i><i></i></span>' : hdot('working')}<span class="ttx">${ags.map(a => esc(wr(a) ? tr('{0} is writing …', a.name) : tr('{0} is working on it', a.name)) + (a.status_text ? ` <span class="muted">· ${esc(a.status_text)}</span>` : '')).join('<br>')}</span></div>`;
}
const agentBusyState = () => { const ags = (S.agents || []).filter(a => a.enabled && !agentOffline(a)); return ags.some(a => a.status === 'working') ? 'working' : ags.some(a => a.status === 'waiting' || a.waiting) ? 'waiting' : ''; };
const agentStatusLines = () => (S.agents || []).filter(a => a.enabled && a.status !== 'idle').map(agentHstLine);  // 2.13.0 (#453 P10): no stale status text while not connected
// live update without re-rendering what someone may be typing in (task panel, chat)
function agentLive() {
  const t = S.sel && taskById(S.sel), d = $('#d-typing');
  if (d) d.outerHTML = typingHtml(taskTypers(t), 'd-typing');
  // 2.12.2 (#451): the typing row and the state chip are swapped only when they changed; the dots appearing make the list
  // shorter, so a list that was at the bottom is put back to the bottom
  const c = $('#chat-typing'), a = S.chat.aid && agentById(S.chat.aid), box = $('#chat-msgs'), pin = !!box && chatNear(box);
  const swap = (el, h) => { if (el && el._h !== h && el.outerHTML !== h) { el.outerHTML = h; const n = $('#' + el.id); if (n) n._h = h; } };
  if (c) swap(c, typingHtml(chatTyping(a) ? [a] : [], 'chat-typing'));
  if (a) swap($('#chat-st'), chatStHtml(a));
  if (pin && box.isConnected && !chatNear(box)) box.scrollTop = box.scrollHeight;
  const st = agentBusyState();
  const more = $('#tabs [data-act="tabs-more"]'), inMore = !!more && tabOverflow().more.some(x => x.id === 'agents');
  $$('#side [data-go="agents"], #tabs [data-go="agents"]').forEach(b => { b.classList.toggle('aspin', st === 'working'); b.classList.toggle('await', st === 'waiting'); });
  if (more) { more.classList.toggle('aspin', st === 'working' && inMore); more.classList.toggle('await', st === 'waiting' && inMore); }
}
// 2.4.1 (#375): an open chat's header follows the clock too (a typing signal runs out after 10 s, "offline" after 5 minutes
// without a poll), without asking the server
setInterval(() => { if (S.chat.aid && !document.hidden && $('#chat-st')) agentLive(); }, 2000);
// 2.6.1 (#402): the header dots follow the clock too ("offline" once an agent stopped polling), without asking the server
let hdSig = '';
setInterval(() => { if (document.hidden || !$('#top')) return; const sg = shownAgents().map(a => a.id + agentHst(a)).join(); if (sg !== hdSig) { const first = !hdSig; hdSig = sg; if (!first) renderTop(); } }, 30000);
// sync while typing in the task panel: no full reload, but the agents' status still comes along
async function agentPoll() {
  if (!agentsOn()) return;
  try { const j = await api('GET', '/api/agents'); if (Array.isArray(j.agents)) { S.agents = j.agents; S.agentsAt = Date.now(); agentLive(); renderTop(); } } catch { /* offline */ }
}

// ---- #285 drag and drop (desktop): scroll the list / sidebar when the pointer comes near the top or bottom edge
// (faster the closer it gets); also left / right in the kanban board
const DS = {on: false, x: 0, y: 0, box: null, raf: 0, last: 0};
const DS_EDGE = 64, DS_MAX = 22;
function dsScrollable(el) {
  for (let n = el; n && n !== document.body; n = n.parentElement) {
    const cs = getComputedStyle(n);
    if ((/(auto|scroll)/.test(cs.overflowY) && n.scrollHeight > n.clientHeight + 1) || (/(auto|scroll)/.test(cs.overflowX) && n.scrollWidth > n.clientWidth + 1)) return n;
  }
  return null;
}
// speed (px per frame) for a pointer at p inside [a, b]: 0 outside the edge zones, up to DS_MAX at (or beyond) the edge
function dsSpeed(p, a, b) {
  const edge = Math.min(DS_EDGE, (b - a) / 4);
  if (p < a + edge) return -Math.ceil(DS_MAX * Math.min(1, (a + edge - p) / edge));
  if (p > b - edge) return Math.ceil(DS_MAX * Math.min(1, (p - (b - edge)) / edge));
  return 0;
}
function dsStep() {
  DS.raf = 0;
  if (!DS.on || !DS.box || !DS.box.isConnected) return;
  const r = DS.box.getBoundingClientRect();
  let moved = false;
  if (DS.x >= r.left - 40 && DS.x <= r.right + 40 && DS.box.scrollHeight > DS.box.clientHeight + 1) {
    const v = dsSpeed(DS.y, r.top, r.bottom);
    if (v) { const b = DS.box.scrollTop; DS.box.scrollTop = b + v; moved = DS.box.scrollTop !== b; }
  }
  if (DS.y >= r.top && DS.y <= r.bottom && DS.box.scrollWidth > DS.box.clientWidth + 1 && /(auto|scroll)/.test(getComputedStyle(DS.box).overflowX)) {
    const v = dsSpeed(DS.x, r.left, r.right);
    if (v) { const b = DS.box.scrollLeft; DS.box.scrollLeft = b + v; moved = moved || DS.box.scrollLeft !== b; }
  }
  if (moved || Date.now() - DS.last < 400) DS.raf = requestAnimationFrame(dsStep);
}
document.addEventListener('dragstart', e => { if (isTouch() && isMobile()) return; if (e.target.closest?.('#view, #side')) { DS.on = true; DS.box = null; } }, true);
document.addEventListener('dragover', e => {
  if (!DS.on) return;
  DS.x = e.clientX; DS.y = e.clientY; DS.last = Date.now();
  const box = dsScrollable(e.target);
  if (box && (box.closest('#view') || box.id === 'view' || box.id === 'side')) DS.box = box;
  else if (!DS.box) DS.box = $('#view');
  if (!DS.raf) DS.raf = requestAnimationFrame(dsStep);
}, true);
const dsStop = () => { DS.on = false; DS.box = null; if (DS.raf) cancelAnimationFrame(DS.raf); DS.raf = 0; };
document.addEventListener('dragend', dsStop, true);
document.addEventListener('drop', dsStop, true);

// ------------------------------------------------------------------ boot
(async () => {
  const i18nBoot = i18nLoad(uiLang());  // last used language (localStorage), in parallel with the state
  try { await load(); if (!S.lists.length) throw new Error('no state'); } catch (e) { if (e.message === 'auth') return; await i18nBoot; $('#view').innerHTML = `<div class="empty">${tr('Server not reachable.')}<br>${tr('Reload the page once the server is reachable again.')}</div>`; return; }
  await i18nBoot; await i18nLoad(uiLang()); S.booted = true;  // render in the server-side language
  // 2.13.0 (#453 A16): the first-run step 2 ("What do you want to use?") was not finished (tab reloaded / closed after the
  // admin account was created): it comes back until "Start" is pressed
  if (S.setupPending && !$('.authscreen')) { const el = document.createElement('div'); el.className = 'modal authscreen'; document.body.appendChild(el); $('#app')?.setAttribute('inert', ''); setupChoices(el, `<div class="alogo">${logoSvg(40)}<b>${APP_NAME}</b></div>`); }
  if (new URLSearchParams(location.search).get('share') === 'err') {
    history.replaceState(null, '', '/#inbox'); await route();
    toast(tr('Share: the file could not be received'));
  } else if (new URLSearchParams(location.search).get('share') === '1') {  // files shared via the service worker
    let meta = {title: '', text: '', url: '', files: []}, files = [];
    try {
      const c = await caches.open('tasks-share');
      const m = await c.match('/share-inbox/meta');
      if (m) meta = await m.json();
      files = await Promise.all(meta.files.map(async (f, i) => { const r = await c.match(`/share-inbox/${i}`); return r ? new File([await r.blob()], f.name, {type: f.type}) : null; }));
      files = files.filter(Boolean);
      await caches.delete('tasks-share');
    } catch { /* no cache api */ }
    // Chrome on Android currently hands over no files to installed web apps (verified 2026-09-25)
    if (!files.length && !meta.text && !meta.url && !meta.title) toast(tr('Please share images and files via the ntfy app (topic inbox)'));
    history.replaceState(null, '', '/#inbox');
    await route();
    // 2.13.1 (#465): "Send to agent": with an agent to chat with, the share sheet asks where it goes (a new task stays the
    // default); the files + text then wait in that agent's chat box, ready to send
    const ags = agentsOn() ? (S.agents || []).filter(a => a.enabled) : [];
    const dest = ags.length && (files.length || meta.text || meta.url || meta.title) ? await shareDest(ags) : 'task';
    if (dest !== 'task') {
      const txt = [meta.title, meta.text, meta.url && !(meta.text || '').includes(meta.url) ? meta.url : ''].map(x => (x || '').trim()).filter(Boolean).join('\n');
      if (txt) S.drafts['chat:' + dest] = txt;
      S.chatFiles[dest] = files.slice(0, 10);
      chatOpen(dest);
    } else {
    // the link goes into the link field; a bare link gets domain + path as title
    const [u, rest] = shareLink(meta.text, meta.url);
    const title = meta.title || rest || (u ? urlTitle(u) : '') || (files[0] ? files[0].name.replace(/\.[^.]+$/, '') : '');
    openQuickSheet(title, {url: u, list_id: inbox().id, files});
    }
  } else if (location.pathname === '/share') {  // Android share sheet (text only, old manifest) -> new task
    const q = new URLSearchParams(location.search);
    const text = (q.get('text') || '').trim();
    history.replaceState(null, '', '/#inbox');
    await route();
    const [u, rest] = shareLink(text, (q.get('url') || '').trim());
    openQuickSheet((q.get('title') || '').trim() || rest || (u ? urlTitle(u) : ''), {url: u, list_id: inbox().id});
  } else if (new URLSearchParams(location.search).get('action') === 'new') {  // app shortcut "New task"
    history.replaceState(null, '', '/' + (location.hash || ''));
    await route();
    openQuickSheet();
  } else if (new URLSearchParams(location.search).get('action') === 'capture') {  // 2.4.0 (#187): app shortcut "Quick add"
    history.replaceState(null, '', '/' + (location.hash || ''));
    await route();
    quickCapture();
  } else if (location.pathname === '/capture') {  // 2.4.0 (#187): the bookmarklet popup (?title&url) or its help page
    const q = new URLSearchParams(location.search), title = (q.get('title') || '').trim().slice(0, 500), u = (q.get('url') || '').trim();
    S.capturePage = true;
    history.replaceState(null, '', '/capture#inbox');
    await route();
    document.body.classList.add('capmode');
    const url = /^https?:\/\//i.test(u) ? u.slice(0, 2000) : '';
    if (title || url) quickCapture(title || (url ? urlTitle(url) : ''), url ? {url} : {});
    else captureHelp();
  } else await route();
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/sw.js').catch(() => {});
    navigator.serviceWorker.addEventListener('message', swMessage);
  }
  setTimeout(wpSync, 3000);
  // v1.1: first start of a new account: "Getting started" list (server side, in the user's language), then the tour
  if (S.settings.onboard === 'pending') {
    try { const j = await api('POST', '/api/onboarding', {touch: isTouch(), mac: IS_MAC}); if (j?.created) { await load(); render(); } } catch { /* offline: next start */ }
  }
  if (S.settings.tour === 'pending' && !new URLSearchParams(location.search).get('share') && !S.capturePage) setTimeout(tourStart, 400);
  setTimeout(quipsLoad, 1500);
})();

// ---- 2.2.0 (#271): Git integration. The list dialog of a project list connects GitHub / Gitea / Forgejo repositories
// (owner + list admins); the task panel shows the linked pull requests (state, CI) and commits ("Code", before the
// comments), rows a chip with the newest pull request; #339: an agent's "ready to merge" comment with Approve / Reject
const PR_ST = {open: N_('open|pr'), merged: N_('merged'), closed: N_('closed|pr')};
const CI_ST = {success: [N_('CI passed'), 'check'], failure: [N_('CI failed'), 'x'], pending: [N_('CI running'), 'clock']};
const GIT_PROV = [['github', 'GitHub'], ['gitea', 'Gitea / Forgejo']];
const listRepos = lid => listById(lid)?.repos || [];
const httpUrl = u => /^https?:\/\//i.test(String(u || '')) ? String(u) : '';
function ciIcon(ci) {
  const x = CI_ST[ci]; if (!x) return '';
  return `<span class="ci ci-${ci}" title="${esc(tr(x[0]))}" aria-label="${esc(tr(x[0]))}">${ic(x[1], 's')}</span>`;
}
function codeChip(t) {
  const p = t.code?.prs?.[0]; if (!p) return '';
  const tip = tr('Pull request #{0}: {1}', p.n, tr(PR_ST[p.state] || p.state)) + (CI_ST[p.ci] ? ' · ' + tr(CI_ST[p.ci][0]) : '');
  return `<span class="gitc pr-${esc(p.state)}" title="${esc(tip)}" aria-label="${esc(tip)}">${ic('pr', 's')}#${p.n}${ciIcon(p.ci)}</span>`;
}
// "Agent working on it": the assignee is an agent that reports "working" on this task
function agentOnIt(t) {
  const a = t && t.assignee_id && agentById(t.assignee_id);
  return a && a.enabled && a.status === 'working' && (a.status_task === t.id || (a.job_tasks || []).includes(t.id)) ? a : null;
}
function prRow(p) {
  const u = httpUrl(p.url), inner = `${ic('pr', 's')}<span class="gst pr-${esc(p.state)}">${esc(tr(PR_ST[p.state] || p.state))}</span><span class="gtt">${esc(p.title || '#' + p.n)}</span><span class="muted gmeta">#${p.n}${p.author ? ' · ' + esc(p.author) : ''}</span>${ciIcon(p.ci)}`;
  return u ? `<a class="gitrow" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${inner}</a>` : `<div class="gitrow">${inner}</div>`;
}
function commitRow(m) {
  const u = httpUrl(m.url), inner = `${ic('commit', 's')}<code>${esc(m.short)}</code><span class="gtt">${esc(m.message)}</span><span class="muted gmeta">${esc(m.author || '')}</span>`;
  return u ? `<a class="gitrow" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${inner}</a>` : `<div class="gitrow">${inner}</div>`;
}
// 2.4.2 (#387): the Code section only where it helps: the list has a repository AND the task has linked pull requests /
// commits, is a bug or a feature, or an agent is assigned (it reports its branch / pull request here); otherwise the
// task's "…" menu offers "Link code…" (copies the branch name)
function codeShown(t) {
  if (!(t?.id > 0) || t.context || !listRepos(t.list_id).length) return false;
  const c = t.code || {};
  return !!(c.prs?.length || c.commits?.length) || t.ttype === 'bug' || t.ttype === 'feature' || (!!t.assignee_id && isAgentUser(t.assignee_id));
}
function codeHtml(t) {
  if (!codeShown(t)) return '';
  const repos = listRepos(t.list_id), c = t.code || {prs: [], commits: []};
  const a = agentOnIt(t);
  const prs = c.prs.map(prRow).join(''), cms = c.commits.map(commitRow).join('');
  const hint = !prs && !cms ? `<div class="muted ghint">${esc(tr('Nothing linked yet: mention #{0} in a commit or pull request, or name the branch {1}.', t.id, `kalmido-${t.id}`))}</div>` : '';
  return `<div class="dsec gitsec" id="d-code"><h5>${tr('Code')}${repos.length ? ` <span class="muted h5note">${esc(repos.map(r => r.full_name).join(', '))}</span>` : ''}${repos.length ? `<button class="iconbtn gref" data-act="git-refresh" data-lid="${t.list_id}" title="${esc(tr('Check the repository now'))}" aria-label="${esc(tr('Check the repository now'))}">${ic('sync', 's')}</button>` : ''}</h5>
    ${a ? `<div class="gitagent" role="status">${ic('bot', 's')}<span>${esc(tr('{0} is working on it', a.name))}</span>${a.status_text ? `<span class="muted">· ${esc(a.status_text)}</span>` : ''}</div>` : ''}${prs ? `<div class="gitl">${prs}</div>` : ''}${cms ? `<div class="gitl">${cms}</div>` : ''}${hint}${repos.length ? `<button class="linkbtn gbranch" data-act="git-branch" data-id="${t.id}" title="${esc(tr('Copy a branch name for this task'))}">${ic('copy', 's')}<code>${esc(gitBranch(t))}</code></button>` : ''}</div>`;
}
const gitBranch = t => `kalmido-${t.id}`;  // 2.5.1 (#396): the id only, no title part (old <prefix>-<id>-slug branches still match)
async function gitCopyBranch(t) {
  try { await navigator.clipboard.writeText(gitBranch(t)); toast(tr('Copied: {0}', gitBranch(t))); } catch { toast(gitBranch(t)); }
}
async function gitRefresh(lid) {
  const rs = listRepos(lid); if (!rs.length) return;
  try { for (const r of rs) await api('POST', `/api/repos/${r.id}/refresh`); } catch { return; }
  toast(tr('Checking the repository …'));
  setTimeout(async () => { await load(); render(); }, 4000);
}
async function gitUndo(tid) {
  try { await api('POST', `/api/tasks/${tid}/git-undo`); } catch { return; }
  toast(tr('Reopened')); await load(); render(); if (S.sel === tid) loadTimeline(tid);
}
function gitActText(a, d, q) {
  const pr = q(`#${d.n} ${d.title || ''}`.trim()), repo = q(d.repo || '');
  if (a.kind === 'git_pr') return d.state === 'merged' ? tr('Pull request {0} was merged in {1}', pr, repo)
    : d.state === 'closed' ? tr('Pull request {0} was closed in {1}', pr, repo) : tr('Pull request {0} was opened in {1}', pr, repo);
  const t = taskById(S.tl.id), undo = t && t.status !== 0 && canEdit(t) && a.id === Math.max(...(S.tl.activity || []).filter(x => x.kind === 'git_done').map(x => x.id))
    ? ` <button class="linkbtn" data-act="git-undo" data-id="${t.id}">${tr('Undo')}</button>` : '';
  return (d.kind === 'pr' ? tr('Completed by the pull request {0} in {1}', q(d.title || ''), repo) : tr('Completed by the commit {0} in {1}', q(d.title || ''), repo)) + undo;
}
// #339: an agent's "ready to merge" comment: the pull request with state + CI, the summary, Approve / Reject (approvers)
function mrHtml(c, s, ro) {
  const t = taskById(S.sel), p = (t?.code?.prs || []).find(x => x.n === s.number && x.repo === s.repo) || {n: s.number, url: s.pr_url, state: 'open', title: ''};
  const st = s.state === 'approved' ? tr('approved') : s.state === 'rejected' ? tr('rejected') : '';
  const may = s.state === 'open' && !ro && S.tl.approver;
  return `<div class="sug mr ${esc(s.state || 'open')}"><div class="sugh">${ic('pr', 's')}<b>${tr('Ready to merge')}</b>${st ? `<span class="muted">· ${st}</span>` : ''}</div>
    <div class="gitl">${prRow(p)}</div>${s.summary ? `<div class="mrsum">${esc(s.summary).replace(/\n/g, '<br>')}</div>` : ''}
    ${may ? `<div class="sugb"><button class="btn sm pri" data-act="mr-ok" data-cid="${c.id}">${ic('check', 's')} ${tr('Approve')}</button><button class="btn sm" data-act="mr-no" data-cid="${c.id}">${ic('x', 's')} ${tr('Reject')}</button><span class="muted">${tr('The agent merges only after your approval')}</span></div>` : ''}</div>`;
}
// list dialog > Repository
function repoBoxHtml(l) {
  return `<h4 id="l-repos-h">${tr('Repository')}</h4><div class="shint lhint">${tr('Pull requests, commits and CI at the tasks of this list: mention #123 (the task number) in a commit or pull request, or name a branch kalmido-123-…. “fixes #123” in a merged pull request completes the task.')}</div><div class="members" id="l-repos"><div class="muted mhint">${tr('Loading…')}</div></div>`;
}
function repoWire(md, lid) {
  const box = $('#l-repos', md); if (!box) return;
  let j = null, edit = null, secret = null;
  const provSel = `<select id="rp-prov" aria-label="${esc(tr('Provider'))}">${GIT_PROV.map(([k, n]) => `<option value="${k}">${n}</option>`).join('')}</select>`;
  const draw = () => {
    if (!md.isConnected) return;
    if (!j) { box.innerHTML = `<div class="muted mhint">${tr('Loading…')}</div>`; return; }
    const rows = j.repos.map(r => `<div class="mrow reporow" data-rid="${r.id}">${ic('git', 's')}<span class="n"><a href="${esc(httpUrl(r.web_url))}" target="_blank" rel="noopener noreferrer">${esc(r.full_name)}</a>
        <span class="muted rpm">${esc(GIT_PROV.find(x => x[0] === r.provider)?.[1] || r.provider)}${r.default_branch ? ' · ' + esc(r.default_branch) : ''}${j.may ? ' · ' + esc(r.token ? tr('Token set') : tr('No token')) + (r.hook ? ' · ' + esc(tr('Webhook on')) : '') : ''}</span>
        <span class="rst rst-${esc(r.status)}">${esc(r.status === 'error' ? r.error : r.status === 'new' ? tr('Waiting for the first check') : tr('Checked {0}', relTime(r.polled_at)))}</span></span>
        <button class="iconbtn" data-rp="refresh" title="${esc(tr('Check the repository now'))}" aria-label="${esc(tr('Check the repository now'))}">${ic('sync', 's')}</button>
        ${j.may ? `<button class="iconbtn" data-rp="menu" title="${esc(tr('More'))}" aria-label="${esc(tr('More'))}">${ic('dots', 's')}</button>` : ''}</div>
      ${edit === r.id ? `<div class="mrow repoedit"><input id="rp-tok2" type="password" autocomplete="off" placeholder="${esc(tr('New access token (empty = remove)'))}" aria-label="${esc(tr('Access token'))}"><button class="btn sm" data-rp="tok-save">${tr('Save')}</button></div>` : ''}
      ${secret && secret.id === r.id ? `<div class="shint lhint rpsec">${esc(tr('Webhook: payload URL {0}, content type JSON, secret (shown only now):', r.hook_url))} <code>${esc(secret.s)}</code></div>` : ''}`).join('');
    const add = j.may && j.repos.length < j.max ? `<div class="repoadd">
        <div class="row"><label for="rp-prov">${tr('Provider')}</label>${provSel}</div>
        <div class="row"><label for="rp-base">${tr('Server')}</label><input id="rp-base" type="url" inputmode="url" autocomplete="off" placeholder="${esc(tr('empty = github.com'))}"></div>
        <div class="row"><label for="rp-name">${tr('Repository')}</label><input id="rp-name" autocomplete="off" placeholder="owner/name"></div>
        <div class="row"><label for="rp-tok">${tr('Access token')}</label><input id="rp-tok" type="password" autocomplete="off" placeholder="${esc(tr('read-only is enough; empty for a public repository'))}" ${j.key ? '' : 'disabled'}></div>
        ${j.key ? '' : `<div class="shint keep lhint">${esc(tr('Set KALMIDO_SECRET_KEY on the server to store repository tokens (32 random bytes, base64)'))}</div>`}
        <div class="row rprow"><span class="spacer"></span><button class="btn sm pri" data-rp="add">${ic('plus', 's')} ${tr('Connect')}</button></div></div>` : '';
    box.innerHTML = rows + (listById(lid)?.kind === 'project' ? add : `<div class="muted mhint">${tr('Make this list a project to connect a repository')}</div>`)
      + (!j.may && !j.repos.length && listById(lid)?.kind === 'project' ? `<div class="muted mhint">${tr('The list owner and list admins connect repositories.')}</div>` : '');
  };
  const reload = async () => { try { j = await api('GET', `/api/lists/${lid}/repos`); } catch { j = {repos: [], may: false, key: true, project: false, max: 0}; } draw(); };
  box.addEventListener('click', async e => {
    const b = e.target.closest('[data-rp]'); if (!b) return;
    const rid = +(b.closest('[data-rid]')?.dataset.rid || b.closest('.repoedit')?.previousElementSibling?.dataset.rid || edit || 0);
    const k = b.dataset.rp;
    if (k === 'add') {
      const body = {provider: $('#rp-prov', box).value, base_url: $('#rp-base', box).value.trim(), repo: $('#rp-name', box).value.trim(), token: $('#rp-tok', box).value.trim()};
      if (!body.repo) { $('#rp-name', box).focus(); return; }
      b.disabled = true;
      try { await api('POST', `/api/lists/${lid}/repos`, body); toast(tr('Repository connected')); } catch { b.disabled = false; return; }
      await reload(); await load(); render();
    } else if (k === 'refresh') {
      try { await api('POST', `/api/repos/${rid}/refresh`); toast(tr('Checking the repository …')); } catch { /* shown */ }
      setTimeout(reload, 4000);
    } else if (k === 'tok-save') {
      try { await api('PATCH', `/api/repos/${edit}`, {token: $('#rp-tok2', box).value.trim()}); toast(tr('Saved')); } catch { return; }
      edit = null; await reload();
    } else if (k === 'menu') {
      const r = j.repos.find(x => x.id === rid); if (!r) return;
      menu(b, [{label: tr('Change access token'), icon: 'lock', fn: () => { edit = rid; secret = null; draw(); $('#rp-tok2', box)?.focus(); }},
        r.hook ? {label: tr('Turn the webhook off'), icon: 'x', fn: async () => { try { await api('PATCH', `/api/repos/${rid}`, {hook: 'off'}); } catch { return; } secret = null; await reload(); }}
          : {label: tr('Turn the webhook on (optional)'), icon: 'zap', title: tr('Only when the Git server can reach this server: it then triggers a check at once'), fn: async () => { let x; try { x = await api('PATCH', `/api/repos/${rid}`, {hook: 'on'}); } catch { return; } secret = {id: rid, s: x.hook_secret}; await reload(); }},
        '-', {label: tr('Remove the repository'), icon: 'trash', cls: 'flag-5', fn: async () => {
          if (!await askConfirm(tr('Remove {0}?', r.full_name), tr('The links to pull requests and commits disappear from the tasks. Completed tasks stay completed.'), {ok: tr('Remove'), danger: true})) return;
          try { await api('DELETE', `/api/repos/${rid}`); } catch { return; }
          await reload(); await load(); render(); }}]);
    }
  });
  box.addEventListener('change', e => { if (e.target.id === 'rp-prov') $('#rp-base', box).placeholder = e.target.value === 'github' ? tr('empty = github.com') : 'https://git.example.com'; });
  reload();
}
